"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[7636],{1843(e,n,t){t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>d,default:()=>m,frontMatter:()=>l,metadata:()=>r,toc:()=>p});const r=JSON.parse('{"id":"part5-deep-learning-and-llms/modern-llm-alignment-orpo-grpo","title":"Modern LLM Post-Training \u2014 DPO, ORPO, KTO, GRPO, RLAIF, and PPO","description":"Post-training discussions become confusing when three different decisions are collapsed into one:","source":"@site/docs/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo","permalink":"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":13,"frontMatter":{"title":"Modern LLM Post-Training \u2014 DPO, ORPO, KTO, GRPO, RLAIF, and PPO","slug":"/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo","description":"Post-training discussions become confusing when three different decisions are collapsed into one:","sidebar_label":"13. Modern LLM post-training","pagination_label":"13. Modern LLM post-training","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"12. LLM fine-tuning","permalink":"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning"},"next":{"title":"Part overview","permalink":"/tutorials/part6-appendices/overview"}}');var a=t(4848),i=t(8453),o=t(8172);const s=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo.html","route":"/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"Modern LLM Post-Training \u2014 DPO, ORPO, KTO, GRPO, RLAIF, and PPO","title":"Modern LLM Post-Training \u2014 DPO, ORPO, KTO, GRPO, RLAIF, and PPO","description":"Post-training discussions become confusing when three different decisions are collapsed into one:","readingMinutes":11,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-build-the-map-before-comparing-acronyms","label":"1) Build the map before comparing acronyms"},{"id":"2-dpo-recap-the-baseline","label":"2) DPO recap (the baseline)"},{"id":"3-orpo-odds-ratio-preference-optimization-hong-et-al-2024","label":"3) ORPO \u2014 Odds\u2011Ratio Preference Optimization (Hong et al., 2024)"},{"id":"4-kto-kahneman-tversky-optimization-ethayarajh-et-al-2024","label":"4) KTO \u2014 Kahneman\u2013Tversky Optimization (Ethayarajh et al., 2024)"},{"id":"5-the-crucial-split-offline-preference-learning-vs-online-rl","label":"5) The crucial split: offline preference learning vs online RL"},{"id":"6-grpo-group-relative-policy-optimization-deepseekmath-and-deepseek-r1","label":"6) GRPO \u2014 Group Relative Policy Optimization (DeepSeekMath and DeepSeek\u2011R1)"},{"id":"7-rlaif-and-constitutional-ai-are-related-not-synonyms","label":"7) RLAIF and Constitutional AI are related, not synonyms"},{"id":"8-choosing-between-them","label":"8) Choosing between them"},{"id":"9-a-practical-enterprise-decision-sequence","label":"9) A practical enterprise decision sequence"},{"id":"10-failure-modes-to-test-explicitly","label":"10) Failure modes to test explicitly"},{"id":"11-primary-papers-and-current-official-documentation","label":"11) Primary papers and current official documentation"}],"html":"<div class=\\"ch\\">\\n\\n\\n\\n<div class=\\"tr-note\\">\\n  <strong>Where this fits</strong>\\n  Chapter 12 covered SFT (supervised fine\u2011tuning) and PEFT (LoRA / QLoRA) \u2014\\n  how to make a base LLM follow your instructions and your domain. This\\n  chapter is about the next step: <em>preference and reward-based\\n  post-training</em> \u2014 how to improve choices after SFT, and how to decide\\n  whether an offline preference objective or an online RL loop matches the\\n  evidence you actually have.\\n</div>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Alignment reading path</strong>\\n  <a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">Chapter 12</a> covers the adaptation stack:\\n  SFT, PEFT, LoRA/QLoRA, evaluation, and an introduction to DPO/RLHF. This\\n  chapter intentionally repeats the DPO/RLHF baseline only so ORPO, KTO, GRPO,\\n  RLAIF, and PPO-style RLHF can be compared in one coherent decision section.\\n</div>\\n\\n<div class=\\"tr-warn\\">\\n  <strong>Current tooling boundary (verified July 2026)</strong>\\n  The algorithms below come from their primary papers. Library APIs move more\\n  quickly: current TRL documentation presents DPO, KTO, and GRPO on its main\\n  trainer API, while ORPO and PPO are experimental. Pin the TRL release and\\n  model revision used by a real experiment; do not copy a trainer signature\\n  from an undated tutorial.\\n</div>\\n\\n<h2 id=\\"1-build-the-map-before-comparing-acronyms\\">1) Build the map before comparing acronyms</h2>\\n\\n<p>Post-training discussions become confusing when three different decisions\\nare collapsed into one:</p>\\n\\n<table>\\n  <tbody><tr><th>Decision</th><th>Question</th><th>Examples</th></tr>\\n  <tr>\\n    <td><strong>Signal source</strong></td>\\n    <td>Who or what says an output is good?</td>\\n    <td>Human comparison, thumbs-up/down, AI judge, unit test, schema validator.</td>\\n  </tr>\\n  <tr>\\n    <td><strong>Data shape</strong></td>\\n    <td>What evidence reaches the trainer?</td>\\n    <td>Demonstration, chosen/rejected pair, binary label, prompt plus numeric reward.</td>\\n  </tr>\\n  <tr>\\n    <td><strong>Optimization method</strong></td>\\n    <td>How are model parameters changed?</td>\\n    <td>SFT, DPO, ORPO, KTO, GRPO, PPO.</td>\\n  </tr>\\n</tbody></table>\\n\\n<p><strong>RLAIF</strong>, for example, describes feedback produced by an AI\\nsystem. That feedback can train a reward model for PPO, create pairs for DPO\\nor ORPO, or create binary labels for KTO. RLAIF is therefore a signal source\\nand data-generation process, not a competing optimizer.</p>\\n\\n<h3 id=\\"1-1-the-classic-rlhf-lineage\\">1.1 The classic RLHF lineage</h3>\\n\\n<p><strong>RLHF</strong> (Christiano et al., 2017; InstructGPT, 2022) commonly\\ncollects human preference pairs, fits a reward model, and then uses PPO to\\noptimize an SFT policy against that learned reward. A KL term or related\\nconstraint limits destructive drift from a reference policy.</p>\\n\\n<p>At the algorithm level, PPO-style RLHF has four distinct roles:\\n<strong>policy</strong>, <strong>reference or old-policy distribution</strong>,\\n<strong>reward model or grader</strong>, and <strong>value/critic estimate</strong>.\\nThat does not mean four complete models must always be resident in VRAM.\\nBackbones can be shared, adapters can separate roles, reference scores can be\\nprecomputed, and components can be sharded or offloaded. The roles explain the\\nalgorithm; a profiler explains the memory bill.</p>\\n\\n<h3 id=\\"1-2-why-direct-preference-methods-appeared\\">1.2 Why direct preference methods appeared</h3>\\n\\n<p><strong>DPO</strong> (Rafailov et al., 2023) showed that, under its preference\\nmodel assumptions, a policy can be optimized directly from chosen/rejected\\npairs without fitting an explicit reward model and without an online PPO\\nrollout loop. KTO and ORPO change the required data or reference-policy role;\\nGRPO returns to online sampling but removes the learned critic. These methods\\ntherefore trade different forms of complexity rather than forming a single\\nstrict ladder from old to new.</p>\\n\\n<h2 id=\\"2-dpo-recap-the-baseline\\">2) DPO recap (the baseline)</h2>\\n\\n<p>DPO assumes a Bradley\u2013Terry preference model and trains directly on triples\\n$(x, y_w, y_l)$ where $y_w$ is the chosen response and $y_l$ is the rejected\\none. The loss is:</p>\\n\\n<div class=\\"eq\\">\\n$\\\\mathcal{L}_{\\\\mathrm{DPO}}\\n= -\\\\log\\\\sigma\\\\!\\\\left(\\n   \\\\beta \\\\log\\\\dfrac{\\\\pi_\\\\theta(y_w|x)}{\\\\pi_{\\\\mathrm{ref}}(y_w|x)}\\n - \\\\beta \\\\log\\\\dfrac{\\\\pi_\\\\theta(y_l|x)}{\\\\pi_{\\\\mathrm{ref}}(y_l|x)}\\n\\\\right)$\\n</div>\\n\\n<p>The objective compares the trainable policy with a fixed reference policy.\\nThe scale $\\\\beta$ controls the strength of that reference-relative\\nregularization; in the common interpretation, larger values penalize departure\\nmore strongly. A strong SFT checkpoint is the usual practical starting point,\\nand the method requires paired preferences whose chosen and rejected responses\\nanswer the same prompt.</p>\\n\\n<p><strong>Operationally:</strong> DPO needs reference log-probabilities, but not\\nnecessarily a second fully resident model throughout training. Current\\nimplementations can keep a frozen reference model, precompute its\\nlog-probabilities, or derive policy and reference behavior from different\\nadapters over one base checkpoint.</p>\\n\\n<ul>\\n  <li><strong>Advantage:</strong> no learned reward model and no on-policy rollout loop.</li>\\n  <li><strong>Risk:</strong> contradictory, position-biased, or trivially easy pairs teach the wrong preference boundary.</li>\\n  <li><strong>Use when:</strong> paired preferences are trustworthy and offline training is sufficient.</li>\\n</ul>\\n\\n<h2 id=\\"3-orpo-odds-ratio-preference-optimization-hong-et-al-2024\\">3) ORPO \u2014 Odds\u2011Ratio Preference Optimization (Hong et al., 2024)</h2>\\n\\n<p>ORPO removes the reference model entirely and merges SFT and preference\\noptimization into a single loss:</p>\\n\\n<div class=\\"eq\\">\\n$\\\\mathcal{L}_{\\\\mathrm{ORPO}}\\n= \\\\mathcal{L}_{\\\\mathrm{SFT}}(y_w \\\\mid x) + \\\\lambda \\\\cdot \\\\mathcal{L}_{\\\\mathrm{OR}}$\\n</div>\\n\\n<p>where $\\\\mathcal{L}_{\\\\mathrm{OR}}$ is the negative log\u2011sigmoid of the\\nlog odds\u2011ratio between the chosen and rejected responses:</p>\\n\\n<div class=\\"eq\\">\\n$\\\\mathcal{L}_{\\\\mathrm{OR}} = -\\\\log\\\\sigma\\\\!\\\\left(\\\\log\\\\dfrac{\\\\mathrm{odds}_\\\\theta(y_w|x)}{\\\\mathrm{odds}_\\\\theta(y_l|x)}\\\\right),\\n\\\\quad \\\\mathrm{odds}_\\\\theta(y|x) = \\\\dfrac{\\\\pi_\\\\theta(y|x)}{1-\\\\pi_\\\\theta(y|x)}$\\n</div>\\n\\n<p>In implementation, those probabilities are computed from sequence log\\nprobabilities or length-normalized token log probabilities. The displayed\\nformula is the intuition; raw full-sequence probabilities are tiny, so real\\ncode works in log space for numerical stability.</p>\\n\\n<p><strong>Why people like it:</strong></p>\\n<ul>\\n  <li>No frozen reference policy is required, so one major source of memory and\\n      compute overhead is removed. The actual saving depends on adapters,\\n      precomputation, sharding, optimizer state, and sequence length; there is\\n      no universal \u201c50 percent\u201d guarantee.</li>\\n  <li>You can go from a base model directly to an aligned model in a single\\n      ORPO training objective rather than running separate SFT and preference\\n      phases. Starting-model and data quality still matter.</li>\\n  <li>The ORPO paper reported competitive results across Phi-2, Llama-2, and\\n      Mistral experiments up to 7B parameters; that is evidence from those\\n      settings, not a guarantee for every domain.</li>\\n</ul>\\n\\n<p><strong>Use when:</strong> you have paired preference data and want the simplest,\\nreference-free candidate to benchmark. In current TRL,\\n<code>ORPOTrainer</code> is experimental and has its own configuration and\\nconstructor contract; do not assume it is a drop-in alias for\\n<code>DPOTrainer</code>.</p>\\n\\n<h2 id=\\"4-kto-kahneman-tversky-optimization-ethayarajh-et-al-2024\\">4) KTO \u2014 Kahneman\u2013Tversky Optimization (Ethayarajh et al., 2024)</h2>\\n\\n<p>KTO removes the requirement for <em>paired</em> preference data. Instead of\\n$(x, y_w, y_l)$ triples, you label each $(x, y)$ as simply\\n<strong>desirable</strong> or <strong>undesirable</strong> \u2014 the kind of data you can\\ncollect at scale from thumbs\u2011up / thumbs\u2011down telemetry.</p>\\n\\n<p>The loss is shaped after Kahneman\u2013Tversky prospect theory: gains on\\ndesirable samples and losses on undesirable samples are weighted\\nasymmetrically (loss aversion). This makes KTO a natural candidate for product\\ntelemetry where users rarely write paired comparisons but can still provide a\\npositive or negative signal. It does not make raw clicks automatically valid\\nlabels: selection bias, accidental clicks, exposure bias, and class imbalance\\nstill need explicit treatment.</p>\\n\\n<p><strong>Use when:</strong> your feedback is binary, unpaired, and noisy\\n(production telemetry, customer ratings). Like DPO, the standard KTO\\nformulation uses a reference-policy baseline; current TRL can precompute those\\nreference log-probabilities.</p>\\n\\n<h2 id=\\"5-the-crucial-split-offline-preference-learning-vs-online-rl\\">5) The crucial split: offline preference learning vs online RL</h2>\\n\\n<p>DPO, ORPO, and KTO are normally <strong>offline</strong>: the training set\\nalready contains responses and preference information. PPO and GRPO are\\n<strong>online policy optimization</strong>: the current policy generates new\\nresponses during training, a reward function scores them, and those fresh\\nsamples drive the update.</p>\\n\\n<table>\\n  <tbody><tr><th>Mode</th><th>Main benefit</th><th>Main risk</th></tr>\\n  <tr>\\n    <td>Offline preference optimization</td>\\n    <td>Reproducible data, simpler infrastructure, no rollout serving loop.</td>\\n    <td>The fixed dataset may not cover behavior produced by the changing policy.</td>\\n  </tr>\\n  <tr>\\n    <td>Online RL</td>\\n    <td>Training explores the policy\'s current outputs and can optimize a direct grader.</td>\\n    <td>Rollouts are expensive, and a flawed reward can be exploited in new ways.</td>\\n  </tr>\\n</tbody></table>\\n\\n<p>This distinction is more useful than saying that one acronym is universally\\n\u201cmore modern.\u201d Choose the loop that matches your feedback and evaluation\\nsystem.</p>\\n\\n<h2 id=\\"6-grpo-group-relative-policy-optimization-deepseekmath-and-deepseek-r1\\">6) GRPO \u2014 Group Relative Policy Optimization (DeepSeekMath and DeepSeek\u2011R1)</h2>\\n\\n<p>GRPO was introduced in the DeepSeekMath work and later used as an important\\nRL component in the DeepSeek\u2011R1 program. It is closer to PPO than to DPO in\\nspirit: the current policy samples responses and learns from rewards. Its key\\nsimplification is that it removes the learned value/critic network and uses\\nrelative rewards within a group of responses instead.</p>\\n\\n<p>For each prompt $x$ you sample a <strong>group</strong> of $G$ responses\\n$\\\\{y_1, \\\\dots, y_G\\\\}$ from the current policy. Each is scored by a reward\\nfunction $r_i$ (which can be a learned reward model, but in practice is\\noften a <em>verifiable</em> signal: unit\u2011test pass/fail, math answer match,\\nformat check). Compute the advantage as the in\u2011group standardization:</p>\\n\\n<div class=\\"eq\\">\\n$A_i = \\\\dfrac{r_i - \\\\mathrm{mean}(r_1,\\\\dots,r_G)}\\n{\\\\mathrm{std}(r_1,\\\\dots,r_G) + \\\\varepsilon}$\\n</div>\\n\\n<p>The small $\\\\varepsilon$ in this teaching form prevents division by zero.\\nIf every response in a group receives the same reward, the group provides no\\nrelative learning signal and should be logged rather than silently treated as\\ninformative.</p>\\n\\n<p>The original family of objectives applies a policy-gradient or clipped\\nupdate using the group-relative advantage and can include a KL penalty against\\na reference policy. Removing the critic reduces one substantial model role and\\nits training burden. It does <em>not</em> guarantee lower total memory or better\\nstability in every system: sampling $G$ completions per prompt is expensive,\\nand sequence length, rollout concurrency, inference acceleration, and optional\\nreference-policy use can dominate the footprint.</p>\\n\\n<p><strong>Why it matters:</strong></p>\\n<ul>\\n  <li>Uses <em>verifiable rewards</em> (RLVR). For math and code you don\'t need\\n      a reward model at all \u2014 graders are deterministic.</li>\\n  <li>The group mean acts as a Monte-Carlo baseline, replacing the learned\\n      value network with comparisons among sibling responses.</li>\\n  <li>The DeepSeek\u2011R1 report describes GRPO-style RL with verifiable and\\n      model-based rewards as one major ingredient in its reasoning gains.</li>\\n</ul>\\n\\n<p><strong>Use when:</strong> your task has a programmatic grader (math, code,\\nJSON\u2011schema compliance, tool\u2011use success) \u2014 i.e. RLVR settings.</p>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Do not reduce DeepSeek\u2011R1 to one optimizer</strong>\\n  DeepSeek\u2011R1 was a multi-stage training pipeline: cold-start supervised data,\\n  reasoning-oriented RL, rejection sampling and additional SFT, followed by\\n  further alignment RL. DeepSeek\u2011R1\u2011Zero was the experiment that began with\\n  large-scale RL without preliminary SFT. \u201cGRPO trained R1\u201d is therefore true\\n  only as a partial description.\\n</div>\\n\\n<h3 id=\\"6-1-current-implementation-caveats\\">6.1 Current implementation caveats</h3>\\n\\n<p>GRPO implementations have continued to evolve. Current TRL documentation\\ndefaults to no KL reference model when <code>beta=0</code> and exposes several\\nloss-normalization choices because the original sequence-level formulation can\\nintroduce response-length bias. Group standard-deviation scaling can also\\ncreate question-difficulty bias. Treat reward scaling, zero-variance groups,\\ncompletion truncation, and length normalization as first-class evaluation\\nvariables, not harmless defaults.</p>\\n\\n<h2 id=\\"7-rlaif-and-constitutional-ai-are-related-not-synonyms\\">7) RLAIF and Constitutional AI are related, not synonyms</h2>\\n\\n<p><strong>RLAIF</strong> (reinforcement learning from AI feedback) uses an AI\\nsystem to produce some or all of the preference signal that human annotators\\nwould otherwise provide. A capable judge can compare response pairs against a\\nrubric, assign scalar scores, or label desirable and undesirable outputs.\\nThose labels may then feed a reward model, DPO, ORPO, KTO, PPO, or another\\noptimizer.</p>\\n\\n<p><strong>Constitutional AI</strong> is a more specific procedure. In the\\noriginal work, a written constitution guides self-critique and revision during\\na supervised phase, then AI-generated preference labels support an RL phase.\\nA normal RLAIF judge does not automatically become Constitutional AI merely\\nbecause its prompt contains a rubric.</p>\\n\\n<p>AI feedback can scale beyond what human labelers can review directly, but\\nthe judge introduces its own position bias, verbosity bias, self-preference,\\nrubric ambiguity, and correlated blind spots. Calibrate it against a\\nhuman-reviewed holdout set, randomize answer order, allow ties or abstention,\\nand keep judge and policy versions in the experiment record. Active learning\\ncan reserve expensive judgments for uncertain or high-impact cases, but the\\nuncertainty rule itself must be evaluated.</p>\\n\\n<h2 id=\\"8-choosing-between-them\\">8) Choosing between them</h2>\\n\\n<table>\\n  <tbody><tr>\\n    <th>Method</th><th>Data shape / mode</th><th>Main training roles</th>\\n    <th>Current TRL status</th><th>Pick when\u2026</th>\\n  </tr>\\n  <tr>\\n    <td>SFT (Ch. 12)</td><td>$(x, y)$ demonstrations; offline</td>\\n    <td>Policy model</td><td>Main API</td><td>You have trusted target responses.</td>\\n  </tr>\\n  <tr>\\n    <td>DPO</td><td>$(x, y_w, y_l)$; offline</td>\\n    <td>Policy + reference log-probabilities</td><td>Main API</td>\\n    <td>Strong baseline; paired preferences are available.</td>\\n  </tr>\\n  <tr>\\n    <td>ORPO</td><td>$(x, y_w, y_l)$; offline</td>\\n    <td>Policy model; reference-free objective</td><td>Experimental</td>\\n    <td>You want to benchmark joint SFT + preference alignment.</td>\\n  </tr>\\n  <tr>\\n    <td>KTO</td><td>$(x, y,\\\\text{label})$; offline</td>\\n    <td>Policy + reference log-probabilities</td><td>Main API</td>\\n    <td>You have useful binary feedback but no pairs.</td>\\n  </tr>\\n  <tr>\\n    <td>GRPO</td><td>Prompt + online rollouts + reward</td>\\n    <td>Policy + grader; optional reference; no critic</td><td>Main API</td>\\n    <td>A reliable grader can score several completions per prompt.</td>\\n  </tr>\\n  <tr>\\n    <td>RLAIF</td><td>AI-generated feedback</td>\\n    <td>Judge plus whichever optimizer you choose</td><td>Not an optimizer</td>\\n    <td>You can calibrate an AI judge against human decisions.</td>\\n  </tr>\\n  <tr>\\n    <td>PPO\u2011RLHF</td><td>Prompt + online rollouts + reward</td>\\n    <td>Policy, old/reference policy, reward, value/critic roles</td><td>Experimental</td>\\n    <td>You need online control and can operate the full RL stack.</td>\\n  </tr>\\n</tbody></table>\\n\\n<p>\u201cMain roles\u201d is deliberately not \u201cmodels in VRAM.\u201d Measure resident weights,\\noptimizer state, activations, KV caches, rollout concurrency, communication,\\nand precomputed artifacts in the implementation you actually run.</p>\\n\\n<h2 id=\\"9-a-practical-enterprise-decision-sequence\\">9) A practical enterprise decision sequence</h2>\\n\\n<ol>\\n  <li>Define the held-out evaluation suite, safety constraints, and acceptable\\n      regressions before changing the model.</li>\\n  <li>Establish a strong <strong>SFT</strong> baseline on domain demonstrations\\n      (LoRA / QLoRA where appropriate \u2014 Chapter 12).</li>\\n  <li>Collect provenance-rich feedback. Thumbs-up/down can seed KTO, while\\n      reviewed chosen/rejected pairs can seed DPO or ORPO. Do not convert\\n      ambiguous telemetry into labels without a sampling and audit policy.</li>\\n  <li>Benchmark at least one simple offline baseline. DPO is a strong default;\\n      KTO fits unpaired labels; ORPO remains a useful reference-free candidate.\\n      Choose from evaluation evidence, not an assumed VRAM percentage.</li>\\n  <li>For extraction, JSON, code, SQL, math, or tool-use tasks with reliable\\n      graders, compare rejection-sampling/SFT baselines with a small\\n      <strong>GRPO</strong> or other online-RL experiment. A narrow grader may\\n      be fewer than 100 lines of Python, but adversarial tests, sandboxing,\\n      observability, and governance are usually the larger job.</li>\\n  <li>Use <strong>RLAIF</strong> when a written rubric and calibrated judge can\\n      expand coverage. DPO, KTO, ORPO, reward-model training, and PPO remain\\n      alternative consumers of that feedback; \u201cRLAIF \u2192 ORPO\u201d is one candidate,\\n      not a universal recipe.</li>\\n  <li>Re-measure the committed product metrics and the full regression suite.\\n      Ship through a canary only when the intended gain survives human review\\n      and safety evaluation.</li>\\n</ol>\\n\\n<div class=\\"tr-warn\\">\\n  <strong>Common pitfall</strong>\\n  Alignment methods reward what you measure. If your reward model \u2014 or your\\n  verifiable grader \u2014 has a loophole, the policy will find it (reward\\n  hacking). Always hold out an evaluation set and inspect samples by hand\\n  every iteration.\\n</div>\\n\\n<h2 id=\\"10-failure-modes-to-test-explicitly\\">10) Failure modes to test explicitly</h2>\\n\\n<ul>\\n  <li><strong>Reward hacking:</strong> the policy satisfies the grader while\\n      violating the real intent.</li>\\n  <li><strong>Preference inconsistency:</strong> annotators or judges apply\\n      different criteria to similar pairs.</li>\\n  <li><strong>Judge bias:</strong> order, length, style, or model-family cues\\n      determine the AI judge\'s choice.</li>\\n  <li><strong>Distribution shift:</strong> offline pairs do not resemble outputs\\n      from the updated policy or production traffic.</li>\\n  <li><strong>Zero-variance groups:</strong> every GRPO completion gets the same\\n      reward, so the prompt contributes no relative signal.</li>\\n  <li><strong>Length and truncation bias:</strong> objective normalization or a\\n      maximum completion length changes what behavior is rewarded.</li>\\n  <li><strong>Capability regression:</strong> target metrics improve while\\n      general instruction following, calibration, or safety deteriorates.</li>\\n</ul>\\n\\n<h2 id=\\"11-primary-papers-and-current-official-documentation\\">11) Primary papers and current official documentation</h2>\\n<ul>\\n  <li><a href=\\"https://arxiv.org/abs/2203.02155\\" target=\\"_blank\\" rel=\\"noreferrer\\">Ouyang et al., 2022 \u2014 Training language models to follow instructions with human feedback</a>.</li>\\n  <li><a href=\\"https://arxiv.org/abs/2305.18290\\" target=\\"_blank\\" rel=\\"noreferrer\\">Rafailov et al., 2023 \u2014 Direct Preference Optimization</a>.</li>\\n  <li><a href=\\"https://arxiv.org/abs/2403.07691\\" target=\\"_blank\\" rel=\\"noreferrer\\">Hong et al., 2024 \u2014 ORPO: Monolithic Preference Optimization without Reference Model</a>.</li>\\n  <li><a href=\\"https://arxiv.org/abs/2402.01306\\" target=\\"_blank\\" rel=\\"noreferrer\\">Ethayarajh et al., 2024 \u2014 KTO: Model Alignment as Prospect Theoretic Optimization</a>.</li>\\n  <li><a href=\\"https://arxiv.org/abs/2402.03300\\" target=\\"_blank\\" rel=\\"noreferrer\\">DeepSeek\u2011AI, 2024 \u2014 DeepSeekMath</a> and <a href=\\"https://arxiv.org/abs/2501.12948\\" target=\\"_blank\\" rel=\\"noreferrer\\">DeepSeek\u2011AI, 2025 \u2014 DeepSeek\u2011R1</a>.</li>\\n  <li><a href=\\"https://arxiv.org/abs/2212.08073\\" target=\\"_blank\\" rel=\\"noreferrer\\">Bai et al., 2022 \u2014 Constitutional AI</a> and <a href=\\"https://arxiv.org/abs/2309.00267\\" target=\\"_blank\\" rel=\\"noreferrer\\">Lee et al., 2023 \u2014 RLAIF</a>.</li>\\n  <li><a href=\\"https://huggingface.co/docs/trl/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Hugging Face TRL \u2014 current trainer index</a>, <a href=\\"https://huggingface.co/docs/trl/dpo_trainer\\" target=\\"_blank\\" rel=\\"noreferrer\\">DPO</a>, <a href=\\"https://huggingface.co/docs/trl/kto_trainer\\" target=\\"_blank\\" rel=\\"noreferrer\\">KTO</a>, <a href=\\"https://huggingface.co/docs/trl/grpo_trainer\\" target=\\"_blank\\" rel=\\"noreferrer\\">GRPO</a>, <a href=\\"https://huggingface.co/docs/trl/orpo_trainer\\" target=\\"_blank\\" rel=\\"noreferrer\\">ORPO</a>, and <a href=\\"https://huggingface.co/docs/trl/ppo_trainer\\" target=\\"_blank\\" rel=\\"noreferrer\\">PPO</a> documentation.</li>\\n</ul>\\n\\n</div>"}'),l={title:"Modern LLM Post-Training \u2014 DPO, ORPO, KTO, GRPO, RLAIF, and PPO",slug:"/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo",description:"Post-training discussions become confusing when three different decisions are collapsed into one:",sidebar_label:"13. Modern LLM post-training",pagination_label:"13. Modern LLM post-training",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},p=[];function h(e){return(0,a.jsx)(o.A,{content:s})}function m(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(h,{...e})}):h()}}}]);